// Compendium Explorer — vanilla JS, no build step.
// Data comes from data/*.json, generated by tools/build_data.py.
(() => {
  "use strict";

  // ------------------------------------------------------------ constants
  const CATS = {
    "verb": { label: "Keyword", group: "Subclass" },
    "fragment": { label: "Fragment", group: "Subclass" },
    "aspect": { label: "Aspect", group: "Subclass" },
    "super": { label: "Super", group: "Subclass" },
    "grenade": { label: "Grenade", group: "Subclass" },
    "melee": { label: "Melee", group: "Subclass" },
    "class-ability": { label: "Class ability", group: "Subclass" },
    "class-trait": { label: "Class trait", group: "Subclass" },
    "exotic-armor": { label: "Exotic armor", group: "Exotics", exotic: true },
    "exotic-weapon": { label: "Exotic weapon", group: "Exotics", exotic: true },
    "exotic-class": { label: "Exotic class item perk", group: "Exotics", exotic: true },
    "armor-set": { label: "Armor set bonus", group: "Armor" },
    "armor-mod": { label: "Armor mod", group: "Armor" },
    "artifact-perk": { label: "Artifact perk", group: "Armor" },
    "weapon-trait": { label: "Weapon trait", group: "Weapons" },
    "origin-trait": { label: "Origin trait", group: "Weapons" },
    "intrinsic": { label: "Weapon frame", group: "Weapons" },
    "weapon-mod": { label: "Weapon mod", group: "Weapons" },
    "weapon-info": { label: "Weapon info", group: "Weapons" },
    "mechanic": { label: "Activity modifier", group: "Mechanics" },
  };
  const ELEMENTS = ["Arc", "Solar", "Void", "Stasis", "Strand", "Prismatic"];
  const CLASSES = ["Hunter", "Titan", "Warlock"];
  // keyword groups worth turning into links inside descriptions
  const LINK_GROUPS = new Set(["Arc", "Solar", "Void", "Stasis", "Strand", "Prismatic"]);
  const LINK_EXTRA = new Set(["Orb of Power", "Armor Charge", "Elemental Pickup", "Elemental Buff", "Elemental Debuff", "Finisher"]);

  const SLOTS = [
    { key: "super", label: "Super", cats: ["super"], max: 1, side: "subclass" },
    { key: "grenade", label: "Grenade", cats: ["grenade"], max: 1, side: "subclass" },
    { key: "melee", label: "Melee", cats: ["melee"], max: 1, side: "subclass" },
    { key: "classAbility", label: "Class ability", cats: ["class-ability"], max: 1, side: "subclass" },
    { key: "aspects", label: "Aspect", cats: ["aspect"], max: 2, side: "subclass" },
    { key: "fragments", label: "Fragment", cats: ["fragment"], max: 6, side: "subclass" },
    { key: "exoticArmor", label: "Exotic armor", cats: ["exotic-armor"], max: 1, side: "gear" },
    { key: "exoticClass", label: "Exotic class perk", cats: ["exotic-class"], max: 2, side: "gear" },
    { key: "exoticWeapon", label: "Exotic weapon", cats: ["exotic-weapon"], max: 1, side: "gear" },
    { key: "weaponPerks", label: "Weapon perk", cats: ["weapon-trait", "origin-trait", "intrinsic"], max: 6, side: "gear" },
    { key: "armorSets", label: "Armor set", cats: ["armor-set"], max: 2, side: "gear" },
    { key: "mods", label: "Armor mod", cats: ["armor-mod"], max: 10, side: "gear" },
    { key: "artifact", label: "Artifact perk", cats: ["artifact-perk"], max: 12, side: "gear" },
  ];
  const SLOT_BY_CAT = {};
  SLOTS.forEach((s) => s.cats.forEach((c) => { SLOT_BY_CAT[c] = s; }));

  // ------------------------------------------------------------ state
  const S = {
    entries: [], byId: new Map(), keywords: [], kwByName: new Map(), meta: null,
    shared: {}, tables: null, sheets: {}, combined: null, glossary: new Map(),
  };
  const app = document.getElementById("app");
  const picker = document.getElementById("picker");

  // ------------------------------------------------------------ utils
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const h = (html) => { const t = document.createElement("template"); t.innerHTML = html.trim(); return t.content; };
  const store = {
    get(k, d) { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* private mode etc. */ } },
  };
  const parseHash = () => {
    const raw = location.hash.replace(/^#\/?/, "");
    const [path, query = ""] = raw.split("?");
    return { parts: path.split("/").filter(Boolean).map(decodeURIComponent), q: new URLSearchParams(query) };
  };
  const go = (hash, replace = false) => {
    if (replace) history.replaceState(null, "", hash); else history.pushState(null, "", hash);
    route();
  };
  const sheetUrl = (src, tabName) => {
    const m = S.meta?.sources?.[src];
    if (!m) return null;
    const tab = m.tabs.find((t) => t.name === tabName);
    return `https://docs.google.com/spreadsheets/d/${m.id}/edit${tab ? `#gid=${tab.gid}` : ""}`;
  };
  const snippet = (text, n = 160) => {
    const flat = text.replace(/\s*\n+\s*/g, " · ");
    return flat.length > n ? flat.slice(0, n - 1) + "…" : flat;
  };

  // ------------------------------------------------------------ text formatting
  function buildCombinedRegex() {
    const parts = [
      "(\\[[^\\]\\n]{1,48}\\])",                 // [PvP value]
      "(↑[^\\s|,;)\\]]+(?:\\s?(?:%|seconds?|x))?)", // ↑enhanced value
    ];
    S.keywords.forEach((k) => parts.push(`(\\b(?:${k.rx})\\b)`));
    S.combined = new RegExp(parts.join("|"), "gi");
  }

  function fmtLine(line) {
    let out = "", last = 0;
    S.combined.lastIndex = 0;
    let m;
    while ((m = S.combined.exec(line))) {
      if (m[0] === "") { S.combined.lastIndex++; continue; }
      out += esc(line.slice(last, m.index));
      if (m[1]) out += `<span class="pvp" title="PvP value">${esc(m[1])}</span>`;
      else if (m[2]) out += `<span class="enh" title="Enhanced / catalyst value">${esc(m[2])}</span>`;
      else {
        const idx = m.slice(3).findIndex((g) => g !== undefined);
        const kw = S.keywords[idx];
        if (kw && (LINK_GROUPS.has(kw.group) || LINK_EXTRA.has(kw.name))) {
          out += `<button type="button" class="kw el-${esc(kw.group)}" data-kw="${esc(kw.name)}" title="Everything about ${esc(kw.name)}">${esc(m[0])}</button>`;
        } else out += esc(m[0]);
      }
      last = m.index + m[0].length;
    }
    return out + esc(line.slice(last));
  }

  function fmt(text) {
    return (text || "").split("\n").map((line) => {
      const body = fmtLine(line);
      return line.trim().endsWith(":") && line.length < 160 ? `<span class="cond">${body}</span>` : body;
    }).join("\n");
  }

  // ------------------------------------------------------------ keyword helpers
  function rolesOf(e) {
    // exotic weapons "produce" their own weapon type, so weapon-type perks light up
    if (e._roles) return e._roles;
    const roles = {};
    for (const [k, v] of Object.entries(e.kw || {})) roles[k] = new Set(v);
    if (e.cat === "exotic-weapon" && e.frame) {
      S.keywords.filter((k) => k.group === "Weapon").forEach((k) => {
        if (new RegExp(`\\b(?:${k.rx})\\b`, "i").test(e.frame)) (roles[k.name] ||= new Set()).add("produce");
      });
    }
    e._roles = roles;
    return roles;
  }
  const makes = (e, k) => rolesOf(e)[k]?.has("produce");
  const uses = (e, k) => rolesOf(e)[k]?.has("use");

  function compatible(a, b) {
    if (a.cls && b.cls && a.cls !== b.cls) return false;
    const sub = new Set(["fragment", "aspect", "super", "grenade", "melee"]);
    if (sub.has(a.cat) && sub.has(b.cat) && a.el && b.el && a.el !== b.el && a.el !== "Prismatic" && b.el !== "Prismatic") return false;
    return true;
  }

  function relatedTo(e, limit = 12) {
    const mine = rolesOf(e);
    const scored = [];
    for (const o of S.entries) {
      if (o === e || o.cat === "verb" || o.cat === "mechanic" || !compatible(e, o)) continue;
      const theirs = rolesOf(o);
      const why = [];
      let score = 0;
      for (const [k, r] of Object.entries(mine)) {
        const t = theirs[k];
        if (!t) continue;
        const grp = S.kwByName.get(k)?.group;
        const w = grp === "Ability" || grp === "General" ? 0.5 : 1;
        if (r.has("produce") && t.has("use")) { score += 2 * w; why.push(`uses your ${k}`); }
        if (r.has("use") && t.has("produce")) { score += 2 * w; why.push(`makes ${k}`); }
      }
      if (score > 0) scored.push({ o, score, why });
    }
    scored.sort((a, b) => b.score - a.score || a.o.name.localeCompare(b.o.name));
    return scored.slice(0, limit);
  }

  // ------------------------------------------------------------ shared rendering
  function tagsFor(e) {
    const c = CATS[e.cat] || { label: e.cat };
    const bits = [`<span class="tag ${c.exotic ? "tag-exotic" : ""}">${esc(c.label)}</span>`];
    if (e.el) bits.push(`<span class="tag tag-el el-${esc(e.el)}">${esc(e.el)}</span>`);
    if (e.cls) bits.push(`<span class="tag tag-cls cls-${esc(e.cls)}">${esc(e.cls)}</span>`);
    if (e.slot && e.cat === "armor-mod") bits.push(`<span class="tag">${esc(e.slot)}</span>`);
    if (e.slot && e.cat === "exotic-weapon") bits.push(`<span class="tag">${esc(e.slot)} slot</span>`);
    return bits.join("");
  }
  const elClass = (e) => (e.el ? `el-${e.el}` : e.weaponEls?.length ? `el-${e.weaponEls[e.weaponEls.length - 1]}` : "");

  function detailHTML(e) {
    const c = CATS[e.cat] || {};
    const kv = [];
    if (e.perk) kv.push(["Exotic perk", e.perk]);
    if (e.frame) kv.push(["Frame", e.frame]);
    if (e.perks?.length) kv.push(["Perks", e.perks.join("\n")]);
    if (e.source) kv.push(["Source", e.source]);
    if (e.artifact) kv.push(["Artifact", `${e.artifact}${e.column ? ` · column ${e.column}` : ""}`]);
    if (e.tags) kv.push(["Artifact focus", e.tags]);
    if (e.cost) kv.push(["Cost", e.cost]);
    if (e.slot && e.cat === "armor-mod") kv.push(["Armor slot", e.slot]);
    if (e.group) kv.push(["Group", e.group]);
    if (e.column && e.cat === "exotic-class") kv.push(["Column", e.column]);
    if (e.stats) kv.push(["Stat changes", e.stats]);
    if (e.note) kv.push(["Notes", e.note]);
    if (e.mods?.length) kv.push(["Modified by", e.mods.join(", ")]);

    const body = e.pieces?.length
      ? e.pieces.map((p) => `<div class="piece"><h4>${esc(p.count)} · ${esc(p.name)}</h4><div class="desc">${fmt(p.desc)}</div></div>`).join("")
      : `<div class="desc">${fmt(e.desc)}</div>`;

    const roles = rolesOf(e);
    const kwChips = Object.entries(roles)
      .filter(([, r]) => r.has("produce") || r.has("use"))
      .map(([k, r]) => {
        const g = S.kwByName.get(k)?.group || "General";
        const role = [r.has("produce") && "makes", r.has("use") && "uses"].filter(Boolean).join(" + ");
        return `<button type="button" class="chip el-${esc(g)}" data-kw="${esc(k)}"><span class="dot"></span>${esc(k)} <span class="role">${role}</span></button>`;
      }).join("");

    const rel = relatedTo(e);
    const relHTML = rel.length
      ? rel.map(({ o, why }) => `<button type="button" data-open="${esc(o.id)}" class="${elClass(o)}"><span class="rel-name" ${CATS[o.cat]?.exotic ? 'style="color:var(--exotic)"' : ""}>${esc(o.name)}</span><span class="tag">${esc(CATS[o.cat]?.label || o.cat)}</span>${o.el ? `<span class="tag tag-el el-${esc(o.el)}">${esc(o.el)}</span>` : ""}<span class="rel-why">${esc([...new Set(why)].slice(0, 3).join(", "))}</span></button>`).join("")
      : `<p class="muted">No obvious keyword links. Check the description for conditions the tagger can't read.</p>`;

    const slot = SLOT_BY_CAT[e.cat];
    const src = sheetUrl("compendium", e.sheet);
    return `
      <button type="button" class="btn btn-quiet back-to-list" data-back>‹ Back to results</button>
      <h2 class="${c.exotic ? "exotic" : ""}">${esc(e.name)}</h2>
      <div class="detail-meta">${tagsFor(e)}</div>
      ${body}
      ${kv.length ? `<section><dl class="kv">${kv.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${fmt(v)}</dd>`).join("")}</dl></section>` : ""}
      ${kwChips ? `<section><h3>Keywords</h3><div class="kwlist">${kwChips}</div></section>` : ""}
      <section><h3>Works well with</h3><div class="related">${relHTML}</div></section>
      <div class="detail-actions">
        ${slot ? `<button type="button" class="btn btn-primary" data-addbuild="${esc(e.id)}">Add to build</button>` : ""}
        ${src ? `<a class="btn" href="${esc(src)}" target="_blank" rel="noopener">Open in the Compendium (${esc(e.sheet)})</a>` : ""}
      </div>
      <p class="legend" style="margin-top:14px"><span class="pvp">[bracketed] = PvP value</span><span class="enh">↑ = enhanced or catalyst value</span><span>? = not yet tested</span></p>`;
  }

  // ------------------------------------------------------------ explore
  function searchEntries({ q, cats, el, cls, kw, role }) {
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    const out = [];
    for (const e of S.entries) {
      if (cats.size && !cats.has(e.cat)) continue;
      if (el && e.el !== el && !(e.weaponEls || []).includes(el)) continue;
      if (cls && e.cls && e.cls !== cls) continue;
      if (cls && !e.cls && ["super", "aspect", "melee", "exotic-armor", "class-ability"].includes(e.cat)) continue;
      if (kw) {
        const r = rolesOf(e)[kw];
        if (!r) continue;
        if (role === "makes" && !r.has("produce")) continue;
        if (role === "uses" && !r.has("use")) continue;
      }
      let score = 0;
      if (terms.length) {
        const name = e.name.toLowerCase();
        const hay = e._hay ||= (e.name + " " + e.desc + " " + (e.perk || "") + " " + (e.perks || []).join(" ") + " " + (e.source || "") + " " + (e.artifact || "")).toLowerCase();
        let ok = true;
        for (const t of terms) {
          if (name === t) score += 50;
          else if (name.startsWith(t)) score += 20;
          else if (name.includes(t)) score += 10;
          else if (hay.includes(t)) score += 1;
          else { ok = false; break; }
        }
        if (!ok) continue;
      }
      out.push({ e, score });
    }
    if (terms.length) out.sort((a, b) => b.score - a.score || a.e.name.localeCompare(b.e.name));
    else out.sort((a, b) => a.e.name.localeCompare(b.e.name));
    return out.map((x) => x.e);
  }

  function readExploreParams() {
    const { q } = parseHash();
    return {
      q: q.get("q") || "",
      cats: new Set((q.get("cat") || "").split(",").filter(Boolean)),
      el: q.get("el") || "",
      cls: q.get("cls") || "",
      kw: q.get("kw") || "",
      role: q.get("role") || "",
      id: q.get("id") || "",
      more: +(q.get("more") || 0),
    };
  }

  function exploreHash(p) {
    const q = new URLSearchParams();
    if (p.q) q.set("q", p.q);
    if (p.cats.size) q.set("cat", [...p.cats].join(","));
    if (p.el) q.set("el", p.el);
    if (p.cls) q.set("cls", p.cls);
    if (p.kw) q.set("kw", p.kw);
    if (p.role) q.set("role", p.role);
    if (p.id) q.set("id", p.id);
    const s = q.toString();
    return "#/explore" + (s ? "?" + s : "");
  }

  function renderExplore() {
    const p = readExploreParams();
    const groups = {};
    Object.entries(CATS).forEach(([k, v]) => (groups[v.group] ||= []).push([k, v]));
    const counts = {};
    S.entries.forEach((e) => { counts[e.cat] = (counts[e.cat] || 0) + 1; });

    // keep the search box (and its focus) between keystrokes
    let shell = app.querySelector(".explore");
    if (!shell) {
      app.innerHTML = `
      <div class="explore">
        <aside class="filters" aria-label="Filters">
          <label class="visually-hidden" for="q">Search</label>
          <input id="q" class="input" type="search" placeholder="Search perks, exotics, mods…" autocomplete="off">
          <details ${window.matchMedia("(max-width: 720px)").matches ? "" : "open"}><summary>Filters</summary><div class="filter-body"></div></details>
        </aside>
        <div class="list-col">
          <div class="results-head"><h2 id="count"></h2><button type="button" class="btn btn-quiet" data-clear>Clear filters</button></div>
          <ul class="results" role="list"></ul>
        </div>
        <article class="detail" aria-live="polite"></article>
      </div>`;
      shell = app.querySelector(".explore");
      const input = shell.querySelector("#q");
      let t;
      input.addEventListener("input", () => {
        clearTimeout(t);
        t = setTimeout(() => { const cur = readExploreParams(); cur.q = input.value; cur.id = ""; go(exploreHash(cur), true); }, 140);
      });
    }
    const input = shell.querySelector("#q");
    if (document.activeElement !== input) input.value = p.q;

    const kwOptions = S.keywords.map((k) => `<option value="${esc(k.name)}" ${p.kw === k.name ? "selected" : ""}>${esc(k.name)} (${esc(k.group)})</option>`).join("");
    shell.querySelector(".filter-body").innerHTML = `
      <div class="filter-group"><h3>Element</h3><div class="chips">${ELEMENTS.map((el) => `<button type="button" class="chip el-${el}" aria-pressed="${p.el === el}" data-f="el" data-v="${el}"><span class="dot"></span>${el}</button>`).join("")}</div></div>
      <div class="filter-group"><h3>Class</h3><div class="chips">${CLASSES.map((c) => `<button type="button" class="chip" aria-pressed="${p.cls === c}" data-f="cls" data-v="${c}">${c}</button>`).join("")}</div></div>
      <div class="filter-group"><h3>Keyword</h3>
        <select class="input" data-kwsel><option value="">Any keyword</option>${kwOptions}</select>
        ${p.kw ? `<div class="chips" style="margin-top:6px">${["", "makes", "uses"].map((r) => `<button type="button" class="chip" aria-pressed="${p.role === r}" data-f="role" data-v="${r}">${r ? (r === "makes" ? "Makes it" : "Uses it") : "Either"}</button>`).join("")}</div>` : ""}
      </div>
      ${Object.entries(groups).map(([g, list]) => `
        <div class="filter-group"><h3>${esc(g)}</h3><div class="chips">${list.map(([k, v]) => `<button type="button" class="chip" aria-pressed="${p.cats.has(k)}" data-f="cat" data-v="${k}">${esc(v.label)} <span class="muted">${counts[k] || 0}</span></button>`).join("")}</div></div>`).join("")}`;

    const results = searchEntries(p);
    const limit = 120 + p.more * 200;
    const kwNote = p.kw ? ` that ${p.role === "makes" ? "make" : p.role === "uses" ? "use" : "mention"} ${p.kw}` : "";
    shell.querySelector("#count").textContent = `${results.length.toLocaleString()} result${results.length === 1 ? "" : "s"}${kwNote}`;
    const list = shell.querySelector(".results");
    list.innerHTML = results.slice(0, limit).map((e) => `
      <li><button type="button" class="result ${elClass(e)}" data-open="${esc(e.id)}" aria-current="${p.id === e.id}">
        <span class="result-top"><span class="result-name ${CATS[e.cat]?.exotic ? "exotic" : ""}">${esc(e.name)}</span>${tagsFor(e)}</span>
        <span class="result-snip">${esc(snippet(e.desc))}</span>
      </button></li>`).join("") +
      (results.length > limit ? `<li><button type="button" class="btn" data-more style="width:100%;margin-top:6px">Show ${Math.min(200, results.length - limit)} more</button></li>` : "") +
      (!results.length ? `<li class="muted" style="padding:12px 0">Nothing matches. Try fewer words, or clear a filter.</li>` : "");

    const detail = shell.querySelector(".detail");
    const sel = p.id && S.byId.get(p.id);
    shell.classList.toggle("has-detail", !!sel);
    detail.innerHTML = sel ? detailHTML(sel) : explainer();
    if (sel && window.matchMedia("(max-width: 720px)").matches) window.scrollTo(0, 0);

    shell.onclick = (ev) => {
      const t = ev.target.closest("button, a");
      if (!t) return;
      const cur = readExploreParams();
      if (t.dataset.f) {
        const { f, v } = t.dataset;
        if (f === "cat") { cur.cats.has(v) ? cur.cats.delete(v) : cur.cats.add(v); }
        else cur[f] = cur[f] === v ? "" : v;
        cur.id = "";
        go(exploreHash(cur), true);
      } else if (t.dataset.open) {
        cur.id = t.dataset.open; go(exploreHash(cur));
      } else if (t.dataset.kw) {
        go(exploreHash({ q: "", cats: new Set(), el: "", cls: cur.cls, kw: t.dataset.kw, role: "", id: glossaryFor(t.dataset.kw)?.id || "" }));
      } else if (t.dataset.clear !== undefined) {
        go("#/explore");
      } else if (t.dataset.more !== undefined) {
        const extra = shell.querySelectorAll(".result").length;
        list.lastElementChild.remove();
        list.insertAdjacentHTML("beforeend", results.slice(extra, extra + 200).map((e) => `
          <li><button type="button" class="result ${elClass(e)}" data-open="${esc(e.id)}"><span class="result-top"><span class="result-name ${CATS[e.cat]?.exotic ? "exotic" : ""}">${esc(e.name)}</span>${tagsFor(e)}</span><span class="result-snip">${esc(snippet(e.desc))}</span></button></li>`).join("") +
          (results.length > extra + 200 ? `<li><button type="button" class="btn" data-more style="width:100%;margin-top:6px">Show more</button></li>` : ""));
      } else if (t.dataset.addbuild) {
        addToBuild(S.byId.get(t.dataset.addbuild));
      } else if (t.dataset.back !== undefined) {
        cur.id = ""; go(exploreHash(cur));
      }
    };
    shell.querySelector("[data-kwsel]").onchange = (ev) => {
      const cur = readExploreParams(); cur.kw = ev.target.value; cur.role = ""; cur.id = ""; go(exploreHash(cur), true);
    };
  }

  function glossaryFor(kw) { return S.glossary.get(kw); }

  function explainer() {
    const n = S.entries.length.toLocaleString();
    return `
      <h2>Look anything up</h2>
      <p>${n} perks, abilities, exotics, mods and mechanics from the Destiny Data Compendium, in one searchable list.</p>
      <p>Pick something to see its exact values and what it works well with. Underlined words like <button type="button" class="kw el-Arc" data-kw="Jolt" style="color:var(--arc);background:none;border:0;padding:0;text-decoration:underline dotted;cursor:pointer;font:inherit">Jolt</button> or <button type="button" class="kw el-Solar" data-kw="Scorch" style="color:var(--solar);background:none;border:0;padding:0;text-decoration:underline dotted;cursor:pointer;font:inherit">Scorch</button> jump to everything that makes or uses that effect.</p>
      <p class="legend"><span class="pvp">[bracketed] = PvP value</span><span class="enh">↑ = enhanced or catalyst value</span><span>? = not yet tested</span></p>
      <p><a href="#/build">Start a build</a> to see which pieces feed each other.</p>`;
  }

  // ------------------------------------------------------------ build planner
  const emptyBuild = () => ({ cls: "", el: "", slots: Object.fromEntries(SLOTS.map((s) => [s.key, []])) });
  let build = loadCurrentBuild();

  function loadCurrentBuild() {
    const b = store.get("d2ce.build", null);
    return normalizeBuild(b);
  }
  function normalizeBuild(b) {
    const base = emptyBuild();
    if (!b) return base;
    base.cls = b.cls || ""; base.el = b.el || "";
    for (const s of SLOTS) base.slots[s.key] = (b.slots?.[s.key] || []).filter((id) => S.byId.has(id)).slice(0, s.max);
    return base;
  }
  const saveCurrent = () => store.set("d2ce.build", build);
  const encodeBuild = (b) => {
    const compact = { c: b.cls, e: b.el, s: Object.fromEntries(Object.entries(b.slots).filter(([, v]) => v.length)) };
    return btoa(unescape(encodeURIComponent(JSON.stringify(compact)))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  };
  const decodeBuild = (str) => {
    try {
      const json = decodeURIComponent(escape(atob(str.replace(/-/g, "+").replace(/_/g, "/"))));
      const c = JSON.parse(json);
      return normalizeBuild({ cls: c.c, el: c.e, slots: c.s });
    } catch { return null; }
  };

  function poolFor(slot, b = build) {
    const { cls, el } = b;
    const shared = (cls && S.shared[cls]) || [[], []];
    let pool = S.entries.filter((e) => slot.cats.includes(e.cat));
    switch (slot.key) {
      case "super":
        pool = pool.filter((e) => (!cls || e.cls === cls) && (!el || el === "Prismatic" || e.el === el));
        break;
      case "grenade":
        if (el === "Prismatic") pool = pool.filter((e) => (e.el === "Prismatic" && (!cls || e.cls === cls)) || shared[0].includes(e.name));
        else pool = pool.filter((e) => (!el || e.el === el) && (!cls || !e.cls || e.cls === cls));
        break;
      case "melee":
        if (el === "Prismatic") pool = pool.filter((e) => (!cls || e.cls === cls) && shared[1].includes(e.name));
        else pool = pool.filter((e) => (!el || e.el === el) && (!cls || e.cls === cls));
        break;
      case "classAbility": {
        pool = pool.filter((e) => !cls || e.cls === cls);
        const seen = new Set();
        pool = pool.filter((e) => (seen.has(e.name) ? false : seen.add(e.name)));
        break;
      }
      case "aspects":
        pool = pool.filter((e) => (!cls || e.cls === cls) && (!el || e.el === el));
        break;
      case "fragments":
        pool = pool.filter((e) => !el || e.el === el);
        break;
      case "exoticArmor":
        pool = pool.filter((e) => !cls || e.cls === cls);
        break;
      case "exoticClass":
        pool = pool.filter((e) => !cls || !e.cls || e.cls === cls);
        break;
      default:
    }
    return pool;
  }

  const selectedEntries = (b = build) => SLOTS.flatMap((s) => b.slots[s.key].map((id) => S.byId.get(id)).filter(Boolean));

  function analyse(b = build) {
    const sel = selectedEntries(b);
    const map = new Map();
    // an equipped grenade/melee/class ability is itself a source of that ability
    const own = { grenade: "Grenade", melee: "Melee", classAbility: "Class Ability" };
    for (const [slotKey, kw] of Object.entries(own)) {
      const e = S.byId.get(b.slots[slotKey][0]);
      if (e) map.set(kw, { k: kw, makers: [e], users: [] });
    }
    for (const e of sel) {
      for (const [k, r] of Object.entries(rolesOf(e))) {
        if (!r.has("produce") && !r.has("use")) continue;
        const row = map.get(k) || { k, makers: [], users: [] };
        if (r.has("produce") && !row.makers.includes(e)) row.makers.push(e);
        if (r.has("use")) row.users.push(e);
        map.set(k, row);
      }
    }
    const rows = [...map.values()].map((r) => {
      const loop = r.makers.length && r.users.length && !(r.makers.length === 1 && r.users.length === 1 && r.makers[0] === r.users[0]);
      r.state = loop ? "loop" : r.users.length && !r.makers.length ? "gap" : r.makers.length && !r.users.length ? "orphan" : "self";
      r.group = S.kwByName.get(r.k)?.group || "General";
      return r;
    });
    const order = { loop: 0, gap: 1, self: 2, orphan: 3 };
    const quiet = (g) => g === "Ability" || g === "General" || g === "Weapon";
    rows.sort((a, b) => order[a.state] - order[b.state] || quiet(a.group) - quiet(b.group) || (b.makers.length + b.users.length) - (a.makers.length + a.users.length));
    return { sel, rows };
  }

  function suggestions(b = build, limit = 14) {
    const { sel, rows } = analyse(b);
    if (!sel.length) return [];
    const chosen = new Set(sel.map((e) => e.id));
    const need = new Map(), have = new Map();
    rows.forEach((r) => {
      if (r.users.length && !r.makers.length) need.set(r.k, r);
      if (r.makers.length) have.set(r.k, r);
    });
    const out = [];
    for (const slot of SLOTS) {
      if (b.slots[slot.key].length >= slot.max && slot.max === 1) continue;
      for (const e of poolFor(slot, b)) {
        if (chosen.has(e.id)) continue;
        let score = 0;
        const why = [];
        for (const [k, r] of Object.entries(rolesOf(e))) {
          const grp = S.kwByName.get(k)?.group;
          const w = grp === "Ability" || grp === "General" || grp === "Weapon" ? 0.4 : 1;
          if (r.has("produce") && need.has(k)) { score += 3 * w; why.push(`makes ${k} your build needs`); }
          if (r.has("use") && have.has(k)) { score += 2 * w; why.push(`uses your ${k}`); }
        }
        if (score >= 2) out.push({ e, slot, score, why });
      }
    }
    out.sort((a, b2) => b2.score - a.score || a.e.name.localeCompare(b2.e.name));
    // keep it varied: no more than 4 per slot type
    const per = {};
    const seenName = new Set();
    return out.filter((x) => {
      const key = x.e.cat + "|" + x.e.name;
      if (seenName.has(key)) return false;
      seenName.add(key);
      return (per[x.slot.key] = (per[x.slot.key] || 0) + 1) <= 4;
    }).slice(0, limit);
  }

  function addToBuild(e, quiet = false) {
    if (!e) return;
    const slot = SLOT_BY_CAT[e.cat];
    if (!slot) return;
    if (e.cls && !build.cls) build.cls = e.cls;
    if (e.el && !build.el && ["super", "aspect", "fragment", "grenade", "melee"].includes(e.cat)) build.el = e.el;
    const list = build.slots[slot.key];
    if (!list.includes(e.id)) {
      if (list.length >= slot.max) list.splice(slot.max - 1, 1);
      list.push(e.id);
    }
    saveCurrent();
    if (!quiet) go("#/build");
  }

  function slotButtons(slot) {
    const ids = build.slots[slot.key];
    const parts = ids.map((id, i) => {
      const e = S.byId.get(id);
      return `<div class="slot filled ${elClass(e)} ${CATS[e.cat]?.exotic ? "exotic" : ""}" role="group" aria-label="${esc(slot.label)}">
        <button type="button" class="btn-quiet" style="all:unset;cursor:pointer;display:flex;flex-direction:column;gap:2px" data-pick="${slot.key}" data-idx="${i}">
          <span class="slot-label">${esc(slot.label)}</span><span class="slot-name">${esc(e.name)}</span></button>
        <button type="button" class="slot-x" data-remove="${slot.key}" data-idx="${i}" aria-label="Remove ${esc(e.name)}">×</button>
      </div>`;
    });
    if (ids.length < slot.max) {
      parts.push(`<button type="button" class="slot empty" data-pick="${slot.key}" data-idx="${ids.length}"><span class="slot-label">${esc(slot.label)}${slot.max > 1 ? ` ${ids.length + 1} of ${slot.max}` : ""}</span><span class="slot-name">Choose…</span></button>`);
    }
    return parts.join("");
  }

  function renderBuild() {
    const { q } = parseHash();
    if (q.get("b")) {
      const b = decodeBuild(q.get("b"));
      if (b) { build = b; saveCurrent(); }
      history.replaceState(null, "", "#/build");
    }
    const { rows } = analyse();
    const sug = suggestions();
    const saved = store.get("d2ce.saved", []);
    const segEl = ELEMENTS.map((el) => `<button type="button" class="el-${el}" aria-pressed="${build.el === el}" data-setel="${el}">${el}</button>`).join("");
    const segCls = CLASSES.map((c) => `<button type="button" class="cls-${c}" aria-pressed="${build.cls === c}" data-setcls="${c}">${c}</button>`).join("");

    const strand = (r) => {
      const pills = (list) => list.map((e) => `<button type="button" class="pill ${elClass(e)}" data-open="${esc(e.id)}" title="${esc(CATS[e.cat]?.label)}">${esc(e.name)}</button>`).join("");
      const left = r.makers.length ? pills(r.makers) : `<span class="pill missing" title="Nothing in this build makes ${esc(r.k)}">nothing makes it</span>`;
      const right = r.users.length ? pills(r.users) : `<span class="pill missing">nothing uses it</span>`;
      return `<div class="strand ${r.state} el-${esc(r.group)}">
        <div class="strand-side makers">${left}</div>
        <button type="button" class="strand-node" data-kw="${esc(r.k)}" title="Look up ${esc(r.k)}">${esc(r.k)}</button>
        <div class="strand-side users">${right}</div></div>`;
    };
    const strong = rows.filter((r) => r.state !== "orphan");
    const orphans = rows.filter((r) => r.state === "orphan");
    const loops = rows.filter((r) => r.state === "loop").length;
    const gaps = rows.filter((r) => r.state === "gap").length;

    app.innerHTML = `
      <div class="build-head">
        <div><h1>Build planner</h1>
        <p>Pick your class, subclass and gear. The web below lines up what each piece makes (Jolt, Orbs, Devour…) against what other pieces need, so dead ends stand out.</p></div>
        <div class="build-controls">
          <button type="button" class="btn" data-share>Copy share link</button>
          <button type="button" class="btn" data-save>Save build</button>
          <button type="button" class="btn btn-quiet" data-reset>Start over</button>
        </div>
      </div>
      <div class="build-controls" style="margin-bottom:16px">
        <span class="seg" role="group" aria-label="Class">${segCls}</span>
        <span class="seg" role="group" aria-label="Subclass">${segEl}</span>
      </div>
      <div class="build-grid">
        <div>
          <section class="loadout" aria-labelledby="h-sub">
            <h2 id="h-sub">${build.el ? `<span class="el-${build.el}" style="color:var(--c)">${esc(build.el)}</span>` : "Subclass"}${build.cls ? ` ${esc(build.cls)}` : ""}</h2>
            <div class="slots">${SLOTS.filter((s) => s.side === "subclass").map(slotButtons).join("")}</div>
          </section>
          <section class="loadout" aria-labelledby="h-gear">
            <h2 id="h-gear">Gear, mods and artifact</h2>
            <div class="slots">${SLOTS.filter((s) => s.side === "gear").map(slotButtons).join("")}</div>
          </section>
          ${saved.length ? `<section class="saved"><h3>Saved builds</h3><ul>${saved.map((s, i) => `<li><a href="#/build?b=${esc(s.code)}">${esc(s.name)}</a><button type="button" class="btn btn-quiet" data-delsaved="${i}" aria-label="Delete ${esc(s.name)}">Delete</button></li>`).join("")}</ul></section>` : ""}
        </div>
        <section class="synergy" aria-labelledby="h-syn">
          <h2 id="h-syn">Synergy web</h2>
          <p class="syn-sub">${rows.length ? `${loops} working loop${loops === 1 ? "" : "s"}, ${gaps} unmet need${gaps === 1 ? "" : "s"}. Tagging is automatic from the Compendium text, so read the descriptions before you commit.` : "Add a few pieces to see how they connect."}</p>
          ${strong.length ? `<div class="web-legend"><span>Made by</span><span>Effect</span><span>Used by</span></div><div class="web">${strong.map(strand).join("")}</div>` : `<p class="syn-empty">${rows.length ? "Nothing feeds anything yet." : "Try an aspect and a couple of fragments first."}</p>`}
          ${orphans.length ? `<details style="margin-top:10px"><summary class="muted" style="cursor:pointer">${orphans.length} effect${orphans.length === 1 ? "" : "s"} made but not used</summary><div class="web" style="margin-top:6px">${orphans.map(strand).join("")}</div></details>` : ""}
          ${sug.length ? `<div class="suggest"><h3>Would fit this build</h3><div class="suggest-list">${sug.map(({ e, slot, why }) => `
            <div class="suggest-item ${elClass(e)}"><div class="s-main"><button type="button" class="s-name" data-open="${esc(e.id)}" ${CATS[e.cat]?.exotic ? 'style="color:var(--exotic)"' : ""}>${esc(e.name)}</button> <span class="tag">${esc(slot.label)}</span><div class="s-why">${esc([...new Set(why)].slice(0, 2).join("; "))}</div></div>
            <button type="button" class="btn" data-add="${esc(e.id)}">Add</button></div>`).join("")}</div></div>` : ""}
        </section>
      </div>`;

    app.onclick = (ev) => {
      const t = ev.target.closest("button, a");
      if (!t) return;
      const d = t.dataset;
      if (d.setel) { build.el = build.el === d.setel ? "" : d.setel; pruneBuild(); saveCurrent(); renderBuild(); }
      else if (d.setcls) { build.cls = build.cls === d.setcls ? "" : d.setcls; pruneBuild(); saveCurrent(); renderBuild(); }
      else if (d.pick) openPicker(SLOTS.find((s) => s.key === d.pick), +d.idx);
      else if (d.remove) { build.slots[d.remove].splice(+d.idx, 1); saveCurrent(); renderBuild(); }
      else if (d.add) { addToBuild(S.byId.get(d.add), true); renderBuild(); }
      else if (d.open) go(`#/explore?id=${encodeURIComponent(d.open)}`);
      else if (d.kw) go(`#/explore?kw=${encodeURIComponent(d.kw)}${glossaryFor(d.kw) ? `&id=${encodeURIComponent(glossaryFor(d.kw).id)}` : ""}`);
      else if (d.reset !== undefined) { build = emptyBuild(); saveCurrent(); renderBuild(); }
      else if (d.share !== undefined) {
        const url = `${location.origin}${location.pathname}#/build?b=${encodeBuild(build)}`;
        navigator.clipboard?.writeText(url).then(() => { t.textContent = "Link copied"; }, () => { prompt("Copy this link", url); });
      } else if (d.save !== undefined) {
        const name = prompt("Name this build", defaultBuildName());
        if (name) { const list = store.get("d2ce.saved", []); list.unshift({ name, code: encodeBuild(build) }); store.set("d2ce.saved", list.slice(0, 30)); renderBuild(); }
      } else if (d.delsaved !== undefined) {
        const list = store.get("d2ce.saved", []); list.splice(+d.delsaved, 1); store.set("d2ce.saved", list); renderBuild();
      }
    };
  }

  function defaultBuildName() {
    const ex = build.slots.exoticArmor[0] && S.byId.get(build.slots.exoticArmor[0]);
    return [build.el, build.cls, ex && `with ${ex.name}`].filter(Boolean).join(" ") || "My build";
  }

  function pruneBuild() {
    // drop picks that no longer fit the chosen class/subclass
    for (const slot of SLOTS) {
      const ok = new Set(poolFor(slot).map((e) => e.id));
      build.slots[slot.key] = build.slots[slot.key].filter((id) => ok.has(id));
    }
  }

  function openPicker(slot, idx) {
    const pool = poolFor(slot);
    const { rows } = analyse();
    const have = new Set(rows.filter((r) => r.makers.length).map((r) => r.k));
    const need = new Set(rows.filter((r) => r.users.length && !r.makers.length).map((r) => r.k));
    const taken = new Set(build.slots[slot.key]);
    const scoreOf = (e) => {
      let s = 0;
      const links = [];
      for (const [k, r] of Object.entries(rolesOf(e))) {
        if (r.has("produce") && need.has(k)) { s += 3; links.push(`makes ${k}`); }
        if (r.has("use") && have.has(k)) { s += 2; links.push(`uses ${k}`); }
      }
      return { s, links };
    };
    const items = pool.filter((e) => !taken.has(e.id)).map((e) => ({ e, ...scoreOf(e) }));
    items.sort((a, b) => b.s - a.s || a.e.name.localeCompare(b.e.name));

    picker.innerHTML = `
      <div class="picker-head">
        <div class="picker-title"><h2>Choose ${esc(slot.label.toLowerCase())}</h2><button type="button" class="btn btn-quiet" data-close aria-label="Close">Close</button></div>
        <input class="input" type="search" placeholder="Filter ${items.length} options…" data-filter>
        ${!build.cls || !build.el ? `<p class="muted" style="margin:0;font-size:.9rem">Pick a class and subclass above to narrow these down.</p>` : ""}
      </div>
      <ul class="picker-list">${items.map(({ e, links }) => `
        <li class="picker-item ${elClass(e)}" data-name="${esc((e.name + " " + e.desc).toLowerCase())}">
          <details><summary><span class="p-name ${CATS[e.cat]?.exotic ? "exotic" : ""}">${esc(e.name)}</span> ${e.cls && !build.cls ? `<span class="tag tag-cls cls-${e.cls}">${e.cls}</span>` : ""} ${e.el && slot.key !== "fragments" && build.el !== e.el ? `<span class="tag tag-el el-${e.el}">${e.el}</span>` : ""}
            ${links.length ? `<div class="p-links">Fits: ${esc(links.slice(0, 3).join(", "))}</div>` : ""}
            <div class="p-snip">${esc(snippet(e.desc, 140))}</div></summary>
            <div class="desc">${fmt(e.desc)}</div></details>
          <button type="button" class="btn btn-primary" data-choose="${esc(e.id)}">Equip</button>
        </li>`).join("") || `<li class="muted" style="padding:12px">Nothing fits this slot with the current class and subclass.</li>`}</ul>`;
    picker.showModal();
    const filter = picker.querySelector("[data-filter]");
    filter.focus();
    filter.oninput = () => {
      const v = filter.value.toLowerCase().trim();
      picker.querySelectorAll(".picker-item").forEach((li) => { li.hidden = v && !li.dataset.name.includes(v); });
    };
    picker.onclick = (ev) => {
      if (ev.target === picker) { picker.close(); return; }
      const t = ev.target.closest("button");
      if (!t) return;
      if (t.dataset.close !== undefined) picker.close();
      else if (t.dataset.choose) {
        const list = build.slots[slot.key];
        const e = S.byId.get(t.dataset.choose);
        if (idx < list.length) list[idx] = e.id; else list.push(e.id);
        if (e.cls && !build.cls) build.cls = e.cls;
        if (e.el && !build.el && slot.side === "subclass") build.el = e.el;
        saveCurrent();
        picker.close();
        renderBuild();
      }
    };
  }

  // ------------------------------------------------------------ boss data
  const BOSS_TABS = [
    ["health", "Boss health"], ["bosses", "Boss notes"], ["weapons", "Weapon damage"],
    ["abilities", "Ability damage"], ["sustained", "Sustained DPS"], ["swap", "Swap DPS"], ["encounters", "Encounter breakdowns"],
  ];
  const isNum = (v) => /^-?[\d,]*\.?\d+%?$/.test(v.trim());
  const toNum = (v) => parseFloat(v.replace(/[,%]/g, ""));

  async function renderBoss(which) {
    which = which || "health";
    if (!S.tables) {
      app.innerHTML = `<p class="loading">Loading boss tables…</p>`;
      S.tables = await (await fetch("data/tables.json")).json();
    }
    const tabs = BOSS_TABS.map(([k, label]) => `<a href="#/boss/${k}" ${k === which ? 'aria-current="page"' : ""}>${label}</a>`).join("");
    const src = (k) => S.meta.sources[k];
    if (which === "encounters") return renderEncounters(tabs);
    const t = S.tables[which];
    if (!t) { app.innerHTML = `<p>That table isn't in the data. <a href="#/boss">Back to boss data</a></p>`; return; }
    const s = src(t.source);
    app.innerHTML = `
      <h1>Boss data</h1>
      <p class="intro">Testing by ${esc(s.author)}. Values are copied as published; open the original for formulas, charts and context.</p>
      <nav class="tabbar" aria-label="Boss tables">${tabs}</nav>
      <div class="table-tools">
        <input class="input" type="search" placeholder="Filter rows…" data-tfilter aria-label="Filter rows">
        <span class="muted" data-tcount></span>
        <a href="${esc(sheetUrl(t.source, t.tab))}" target="_blank" rel="noopener">Open “${esc(t.tab)}” in ${esc(s.title)}</a>
      </div>
      <div class="tablewrap" data-twrap></div>`;
    mountTable(app.querySelector("[data-twrap]"), t, app.querySelector("[data-tfilter]"), app.querySelector("[data-tcount]"));
  }

  function mountTable(wrap, t, filterInput, countEl) {
    let sortCol = -1, dir = 1;
    const numericCols = t.columns.map((_, i) => {
      const vals = t.rows.map((r) => r[i]).filter((v) => v && v !== "/" && v !== "N/A");
      return vals.length > 0 && vals.filter(isNum).length / vals.length > 0.7;
    });
    const draw = () => {
      const f = (filterInput?.value || "").toLowerCase().trim();
      let rows = f ? t.rows.filter((r) => r.join(" ").toLowerCase().includes(f)) : t.rows.slice();
      if (sortCol >= 0) {
        rows.sort((a, b) => {
          const x = a[sortCol] || "", y = b[sortCol] || "";
          if (numericCols[sortCol]) {
            const nx = isNum(x) ? toNum(x) : -Infinity, ny = isNum(y) ? toNum(y) : -Infinity;
            return (nx - ny) * dir;
          }
          return x.localeCompare(y) * dir;
        });
      }
      if (countEl) countEl.textContent = `${rows.length} of ${t.rows.length} rows`;
      wrap.innerHTML = `<table class="data"><thead><tr>${t.columns.map((c, i) => `<th scope="col" ${i === sortCol ? `aria-sort="${dir > 0 ? "ascending" : "descending"}"` : ""}><button type="button" data-sort="${i}">${esc(c)}</button></th>`).join("")}</tr></thead>
        <tbody>${rows.map((r) => `<tr>${t.columns.map((_, i) => {
          const v = r[i] || "";
          const cls = numericCols[i] && isNum(v) ? "num" : v.length > 40 ? "wrap" : "";
          return `<td class="${cls}">${esc(v)}</td>`;
        }).join("")}</tr>`).join("")}</tbody></table>`;
    };
    wrap.onclick = (ev) => {
      const b = ev.target.closest("[data-sort]");
      if (!b) return;
      const i = +b.dataset.sort;
      if (sortCol === i) dir = -dir; else { sortCol = i; dir = numericCols[i] ? -1 : 1; }
      draw();
    };
    if (filterInput) filterInput.oninput = draw;
    draw();
  }

  function renderEncounters(tabs) {
    const enc = S.tables.encounters;
    const names = Object.keys(enc);
    const { q } = parseHash();
    const pick = q.get("e") && enc[q.get("e")] ? q.get("e") : names[0];
    app.innerHTML = `
      <h1>Boss data</h1>
      <p class="intro">How each boss's health bar was measured: damage dealt per hit against the percentage of health removed. From ${esc(S.meta.sources.bosshealth.author)}'s Boss Health sheet.</p>
      <nav class="tabbar" aria-label="Boss tables">${tabs}</nav>
      <div class="table-tools">
        <label for="encsel" class="visually-hidden">Encounter</label>
        <select id="encsel" class="input" style="max-width:340px">${names.map((n) => `<option ${n === pick ? "selected" : ""}>${esc(n)}</option>`).join("")}</select>
        <a href="${esc(sheetUrl("bosshealth", pick))}" target="_blank" rel="noopener">Open this tab in the original</a>
      </div>
      <div class="tablewrap" data-twrap></div>`;
    mountTable(app.querySelector("[data-twrap]"), enc[pick]);
    app.querySelector("#encsel").onchange = (ev) => go(`#/boss/encounters?e=${encodeURIComponent(ev.target.value)}`, true);
  }

  // ------------------------------------------------------------ sheet viewer
  async function renderSheets(src, gid) {
    const sources = S.meta.sources;
    src = sources[src] ? src : "compendium";
    if (!S.sheets[src]) {
      app.innerHTML = `<p class="loading">Loading ${esc(sources[src].title)}…</p>`;
      S.sheets[src] = await (await fetch(`data/sheets/${src}.json`)).json();
    }
    const tabs = S.sheets[src];
    const tab = tabs.find((t) => t.gid === gid) || tabs[0];
    const covered = new Set();
    const spans = new Map();
    tab.merges.forEach(([r, c, rs, cs]) => {
      spans.set(`${r},${c}`, [rs, cs]);
      for (let i = 0; i < rs; i++) for (let j = 0; j < cs; j++) if (i || j) covered.add(`${r + i},${c + j}`);
    });
    const links = new Map(tab.links.map(([r, c, text, href]) => [`${r},${c}`, href]));
    const width = Math.max(1, ...tab.grid.map((r) => r.length), ...tab.merges.map(([, c, , cs]) => c + cs));
    const rowsHTML = tab.grid.map((row, r) => {
      if (!row.length && ![...spans.keys()].some((k) => k.startsWith(r + ","))) return "";
      let tds = "";
      for (let c = 0; c < width; c++) {
        const key = `${r},${c}`;
        if (covered.has(key)) continue;
        const v = row[c] || "";
        const sp = spans.get(key);
        const attrs = sp ? `${sp[0] > 1 ? ` rowspan="${sp[0]}"` : ""}${sp[1] > 1 ? ` colspan="${sp[1]}"` : ""}` : "";
        const href = links.get(key);
        const inner = src === "compendium" ? fmt(v) : esc(v);
        tds += `<td${attrs}${v.length > 140 ? ' class="long"' : ""}>${href && /^https?:/.test(href) ? `<a href="${esc(href)}" target="_blank" rel="noopener">${inner}</a>` : inner}</td>`;
      }
      return `<tr>${tds}</tr>`;
    }).join("");
    app.innerHTML = `
      <h1>Original sheets</h1>
      <p class="intro">Every tab as published, layout included, for anything the structured views don't cover (Game Mechanics tables, changelogs, testing notes, legacy tabs).</p>
      <div class="sheet-pick">
        <label class="visually-hidden" for="srcsel">Spreadsheet</label>
        <select id="srcsel" class="input">${Object.entries(sources).map(([k, s]) => `<option value="${k}" ${k === src ? "selected" : ""}>${esc(s.title)}</option>`).join("")}</select>
        <label class="visually-hidden" for="tabsel">Tab</label>
        <select id="tabsel" class="input">${tabs.map((t) => `<option value="${t.gid}" ${t === tab ? "selected" : ""}>${esc(t.name)}</option>`).join("")}</select>
        <a href="https://docs.google.com/spreadsheets/d/${esc(sources[src].id)}/edit#gid=${esc(tab.gid)}" target="_blank" rel="noopener">Open in Google Sheets</a>
        <span class="muted">by ${esc(sources[src].author)}</span>
      </div>
      <div class="tablewrap" style="max-height:calc(100vh - 220px)"><table class="sheet"><tbody>${rowsHTML}</tbody></table></div>`;
    app.querySelector("#srcsel").onchange = (ev) => go(`#/sheets/${ev.target.value}`, true);
    app.querySelector("#tabsel").onchange = (ev) => go(`#/sheets/${src}/${ev.target.value}`, true);
    app.onclick = (ev) => {
      const k = ev.target.closest("[data-kw]");
      if (k) go(`#/explore?kw=${encodeURIComponent(k.dataset.kw)}`);
    };
  }

  // ------------------------------------------------------------ about / credits
  function renderAbout() {
    const fetched = S.meta.fetched ? new Date(S.meta.fetched).toLocaleDateString(undefined, { dateStyle: "long" }) : "unknown";
    const cards = Object.entries(S.meta.sources).map(([k, s]) => `
      <article class="source">
        <h2>${esc(s.title)}</h2>
        <p class="by">by ${esc(s.author)}</p>
        <p>${esc(s.blurb)}</p>
        <ul>
          <li><a href="https://docs.google.com/spreadsheets/d/${esc(s.id)}/edit" target="_blank" rel="noopener">Original spreadsheet</a> (${s.tabs.length} tabs)</li>
          <li>${esc(s.contact)}</li>
          ${s.support ? `<li><a href="${esc(s.support)}" target="_blank" rel="noopener">${k === "compendium" ? "Support the Compendium on Patreon" : "Follow their testing"}</a></li>` : ""}
        </ul>
      </article>`).join("");
    app.innerHTML = `
      <div class="about">
        <h1>Credits</h1>
        <p>All of the numbers here come from community testers who spend hundreds of hours measuring the game. This site only re-arranges their published spreadsheets so they're easier to search and cross-reference. Corrections belong with the original authors, and the original sheets are always the source of truth.</p>
        <div class="sources">${cards}</div>
        <h2>About this mirror</h2>
        <p>Data last copied on ${esc(fetched)}. Text is copied verbatim; keyword tags and synergy links are generated automatically and can be wrong.</p>
        <p>Unofficial fan project. Not affiliated with Bungie or with the spreadsheet authors. Destiny 2 is a trademark of Bungie, Inc.</p>
      </div>`;
  }

  // ------------------------------------------------------------ router
  function route() {
    const { parts } = parseHash();
    const page = parts[0] || "explore";
    document.querySelectorAll("[data-nav]").forEach((a) => {
      if (a.dataset.nav === page) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current");
    });
    if (page !== "explore") app.onclick = null;
    if (page === "build") renderBuild();
    else if (page === "boss") renderBoss(parts[1]);
    else if (page === "sheets") renderSheets(parts[1], parts[2]);
    else if (page === "about") renderAbout();
    else renderExplore();
    if (page !== "explore") window.scrollTo(0, 0);
  }

  function footer() {
    const s = S.meta.sources;
    document.getElementById("sitefoot").innerHTML =
      `Data from the <a href="https://docs.google.com/spreadsheets/d/${s.compendium.id}/edit" target="_blank" rel="noopener">Destiny Data Compendium</a> and ${esc(s.bossdamage.author)}'s <a href="https://docs.google.com/spreadsheets/d/${s.bossdamage.id}/edit" target="_blank" rel="noopener">Boss Damage</a> and <a href="https://docs.google.com/spreadsheets/d/${s.bosshealth.id}/edit" target="_blank" rel="noopener">Boss Health</a> sheets. <a href="#/about">Full credits</a>. Unofficial; not affiliated with Bungie.`;
  }

  async function init() {
    try {
      const [ent, meta] = await Promise.all([
        fetch("data/entries.json").then((r) => r.json()),
        fetch("data/meta.json").then((r) => r.json()),
      ]);
      S.entries = ent.entries;
      S.keywords = ent.keywords;
      S.shared = ent.prismaticShared || {};
      S.meta = meta;
      S.entries.forEach((e) => S.byId.set(e.id, e));
      S.keywords.forEach((k) => S.kwByName.set(k.name, k));
      // glossary entries (subclass "verbs") double as keyword definitions
      S.entries.filter((e) => e.cat === "verb").forEach((e) => {
        for (const k of S.keywords) {
          if (!S.glossary.has(k.name) && new RegExp(`^(?:${k.rx})$`, "i").test(e.name.trim())) S.glossary.set(k.name, e);
        }
      });
      buildCombinedRegex();
      build = loadCurrentBuild();
      footer();
      window.addEventListener("hashchange", route);
      route();
    } catch (err) {
      console.error(err);
      app.innerHTML = `<h1>Couldn't load the data</h1><p>The data files didn't load (${esc(err.message)}). If you opened index.html straight from disk, serve the folder instead, for example <code>python -m http.server</code>, then open the address it prints.</p>`;
    }
  }

  init();
})();
